// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAccounts List ledger accounts
	// (GET /admin/v1/accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// CreateAccount Open a spot account
	// (POST /admin/v1/accounts)
	CreateAccount(ctx context.Context, request CreateAccountRequestObject) (CreateAccountResponseObject, error)
	// GetAccount Get one account
	// (GET /admin/v1/accounts/{id})
	GetAccount(ctx context.Context, request GetAccountRequestObject) (GetAccountResponseObject, error)
	// GetAccountBalances Cached balances of a spot account
	// (GET /admin/v1/accounts/{id}/balances)
	GetAccountBalances(ctx context.Context, request GetAccountBalancesRequestObject) (GetAccountBalancesResponseObject, error)
	// SetAccountStatus Freeze or reactivate an account
	// (PUT /admin/v1/accounts/{id}/status)
	SetAccountStatus(ctx context.Context, request SetAccountStatusRequestObject) (SetAccountStatusResponseObject, error)
	// ListAuditEvents Audit trail, newest first
	// (GET /admin/v1/audit-events)
	ListAuditEvents(ctx context.Context, request ListAuditEventsRequestObject) (ListAuditEventsResponseObject, error)
	// CreateAdjustment Post a manual adjustment against the external account
	// (POST /admin/v1/ledger/adjustments)
	CreateAdjustment(ctx context.Context, request CreateAdjustmentRequestObject) (CreateAdjustmentResponseObject, error)
	// ListEntries Journal entries with postings, newest first
	// (GET /admin/v1/ledger/entries)
	ListEntries(ctx context.Context, request ListEntriesRequestObject) (ListEntriesResponseObject, error)
	// GetTrialBalance Trial balance per asset (must be zero) and house account balances
	// (GET /admin/v1/ledger/trial-balance)
	GetTrialBalance(ctx context.Context, request GetTrialBalanceRequestObject) (GetTrialBalanceResponseObject, error)
	// ListMarkets Markets of the tenant
	// (GET /admin/v1/markets)
	ListMarkets(ctx context.Context, request ListMarketsRequestObject) (ListMarketsResponseObject, error)
	// SetMarketStatus Halt, resume or delist a market
	// (PUT /admin/v1/markets/{symbol}/status)
	SetMarketStatus(ctx context.Context, request SetMarketStatusRequestObject) (SetMarketStatusResponseObject, error)
	// ListSweeps Recent collections into the hot wallet
	// (GET /admin/v1/sweeps)
	ListSweeps(ctx context.Context, request ListSweepsRequestObject) (ListSweepsResponseObject, error)
	// ListWithdrawalsForReview The withdrawal review queue
	// (GET /admin/v1/withdrawals)
	ListWithdrawalsForReview(ctx context.Context, request ListWithdrawalsForReviewRequestObject) (ListWithdrawalsForReviewResponseObject, error)
	// ResolveWithdrawal Unstick a withdrawal the machine could not finish
	// (POST /admin/v1/withdrawals/{id}/resolve)
	ResolveWithdrawal(ctx context.Context, request ResolveWithdrawalRequestObject) (ResolveWithdrawalResponseObject, error)
	// ReviewWithdrawal Approve or reject a withdrawal awaiting review
	// (POST /admin/v1/withdrawals/{id}/review)
	ReviewWithdrawal(ctx context.Context, request ReviewWithdrawalRequestObject) (ReviewWithdrawalResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

